-- Draft procurement and approval foundation; depends on 001–003.
begin;
create table erp.suppliers(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, legacy_id uuid unique references public.suppliers, active boolean not null default true);
create table erp.purchase_requests(id uuid primary key default gen_random_uuid(), code text unique not null, requested_by uuid references auth.users, status text not null default 'draft' check(status in ('draft','pending','approved','rejected','closed')));
create table erp.purchase_request_lines(id uuid primary key default gen_random_uuid(), request_id uuid not null references erp.purchase_requests, item_id uuid not null references erp.items, quantity numeric(18,6) not null check(quantity>0));
create table erp.purchase_orders(id uuid primary key default gen_random_uuid(), code text unique not null, supplier_id uuid not null references erp.suppliers, status text not null default 'draft' check(status in ('draft','pending','approved','partial','received','closed','cancelled')), order_date date not null default current_date, expected_date date);
create table erp.purchase_order_lines(id uuid primary key default gen_random_uuid(), order_id uuid not null references erp.purchase_orders, request_line_id uuid references erp.purchase_request_lines, item_id uuid not null references erp.items, quantity numeric(18,6) not null check(quantity>0), unit_price numeric(24,8) not null check(unit_price>=0));
create table erp.receipts(id uuid primary key default gen_random_uuid(), order_id uuid not null references erp.purchase_orders, stock_document_id uuid unique references erp.stock_documents, received_at timestamptz not null default now());
create table erp.receipt_lines(id uuid primary key default gen_random_uuid(), receipt_id uuid not null references erp.receipts, order_line_id uuid not null references erp.purchase_order_lines, lot_id uuid not null references erp.lots, quantity numeric(18,6) not null check(quantity>0));
create table erp.supplier_invoices(id uuid primary key default gen_random_uuid(), supplier_id uuid not null references erp.suppliers, invoice_number text not null, invoice_date date not null, due_date date, journal_entry_id uuid unique references erp.journal_entries, unique(supplier_id,invoice_number));
create table erp.supplier_invoice_lines(id uuid primary key default gen_random_uuid(), invoice_id uuid not null references erp.supplier_invoices, order_line_id uuid references erp.purchase_order_lines, amount numeric(24,8) not null check(amount>=0));
create table erp.landed_costs(id uuid primary key default gen_random_uuid(), receipt_id uuid not null references erp.receipts, description text not null, amount numeric(24,8) not null check(amount>=0), allocation_method text not null check(allocation_method in ('weight','direct')));
create table erp.landed_cost_allocations(cost_id uuid references erp.landed_costs, receipt_line_id uuid references erp.receipt_lines, amount numeric(24,8) not null check(amount>=0), primary key(cost_id,receipt_line_id));
create table erp.approval_rules(id uuid primary key default gen_random_uuid(), document_type text not null, minimum_amount numeric(24,8) not null default 0 check(minimum_amount>=0), active boolean not null default true);
create table erp.approval_rule_steps(rule_id uuid references erp.approval_rules, step_no integer check(step_no>0), role_id uuid not null references erp.roles, primary key(rule_id,step_no));
create table erp.approval_requests(id uuid primary key default gen_random_uuid(), rule_id uuid not null references erp.approval_rules, document_type text not null, document_id uuid not null, requested_by uuid not null references auth.users, rule_snapshot jsonb not null, status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')));
create table erp.approval_decisions(request_id uuid references erp.approval_requests, step_no integer check(step_no>0), actor_id uuid not null references auth.users, decision text not null check(decision in ('approved','rejected')), decided_at timestamptz not null default now(), primary key(request_id,step_no));
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Posting must enforce order/receipt/invoice consistency, allocation totals,
-- approval sequence and no self-approval, partial receipt limits and authorization.
